using System.Text;
using UnityEngine;
using Zombera.World.CityPipeline.WorldBuilder;

public static class InfrastructureAudit
{
    public static string Execute()
    {
        var service = UnityEngine.Object.FindFirstObjectByType<WorldBuilderService>(FindObjectsInactive.Include);
        var artifacts = service?.Artifacts;
        if (artifacts == null)
            return "WorldBuilder artifacts missing";

        var report = new StringBuilder();
        for (var i = 0; artifacts.Tunnels != null && i < artifacts.Tunnels.Count; i++)
        {
            var tunnel = artifacts.Tunnels[i];
            var core = 0f;
            for (var sample = 0; sample <= 24; sample++)
            {
                var point = Vector2.Lerp(tunnel.EntryXZ, tunnel.ExitXZ, sample / 24f);
                core = Mathf.Max(core, artifacts.Orogen?.SampleOrogenCoreMask(point.x, point.y) ?? 0f);
            }

            report.Append("T#").Append(tunnel.RoadId)
                .Append(" len=").Append(tunnel.LengthMeters.ToString("F0"))
                .Append(" cover=").Append(tunnel.PeakCoverMeters.ToString("F0"))
                .Append(" core=").Append(core.ToString("F2")).Append("; ");
        }

        return report.Length == 0 ? "no tunnels" : report.ToString();
    }
}
